/* Prioritize only above-the-fold images; leave offscreen media lazy. */
(()=>{'use strict';let busy=false;function prioritize(){busy=false;const root=document.getElementById('main-content');if(!root||document.documentElement.dataset.patiView!=='home')return;const selectors=['.stories-section img','.pati-feed-post img','.pati-post img'];let picked=0;for(const sel of selectors){for(const img of root.querySelectorAll(sel)){if(picked>=12)break;if(img.dataset.bucheeFast==='1')continue;const rect=img.getBoundingClientRect();if(rect.top>window.innerHeight*1.3||rect.bottom<0)continue;img.dataset.bucheeFast='1';img.loading='eager';img.decoding='async';img.fetchPriority=picked<7?'high':'auto';picked++}}}function schedule(){if(busy)return;busy=true;requestAnimationFrame(prioritize)}document.addEventListener('DOMContentLoaded',schedule);document.addEventListener('patiyiz:pull-refresh',schedule);new MutationObserver(schedule).observe(document.getElementById('main-content')||document.body,{subtree:true,childList:true});schedule()})();